function arrToList(arr) {
  let head = null, tail = null;
  for (const val of arr) {
    const node = { val, next: null };
    if (!head) { head = node; tail = node; }
    else { tail.next = node; tail = node; }
  }
  return head;
}

function listToArr(head) {
  const result = [];
  let node = head;
  while (node) { result.push(node.val); node = node.next; }
  return result;
}

function reverseList(headArr) {
  let head = arrToList(headArr);
  let prev = null;
  let curr = head;
  while (curr) {
    const next = curr.next;
    curr.next = prev;
    prev = curr;
    curr = next;
  }
  return listToArr(prev);
}

